def _migrate_v5_to_v6_sync(conn: sqlite3.Connection) -> None:
    """Add nullable audit caller field without deleting v5 usage data."""
    table = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'request_audit'"
    ).fetchone()
    if table is None:
        return
    columns = {str(row["name"]) for row in conn.execute("PRAGMA table_info(request_audit)")}
    conn.execute("BEGIN")
    try:
        if "caller" not in columns:
            conn.execute("ALTER TABLE request_audit ADD COLUMN caller TEXT")
        conn.execute("COMMIT")
    except Exception:
        conn.execute("ROLLBACK")
        raise

