const _missingProfileWarned = new Set();

async function readProfile(fetchJSON, profileUri, actorPeerId = "") {
  // Existence pre-check: a missing profile.md used to turn into a content/read
  // 404 on every injection. Check the parent directory first and skip the read
  // entirely when the file is absent (warn once per URI).
  const slash = profileUri.lastIndexOf("/");
  const parentUri = slash > 0 ? profileUri.slice(0, slash) : "";
  if (parentUri) {
    const lsRes = await fetchJSON(
      `/api/v1/fs/ls?uri=${encodeURIComponent(parentUri)}&output=original`,
      {},
      { actorPeerId, caller: "profile-inject" },
    );
    const entries = lsRes.ok && Array.isArray(lsRes.result) ? lsRes.result : null;
    if (entries && !entries.some((e) => e?.name === "profile.md")) {
      if (!_missingProfileWarned.has(profileUri)) {
        _missingProfileWarned.add(profileUri);
        console.warn(`[openviking] profile.md missing at ${profileUri}; skipping injection`);
      }
      return null;
    }
  }
  const res = await fetchJSON(
    `/api/v1/content/read?uri=${encodeURIComponent(profileUri)}`,
    {},
    { actorPeerId, caller: "profile-inject" },
  );
  if (!res.ok || typeof res.result !== "string") return null;
  const trimmed = res.result.trim();
  return trimmed || null;
}

